package com.bananalab.lite;
import org.json.*;import android.content.*;
public class Stage36MemoryCheck{
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();SharedPreferences p=c.getSharedPreferences("banana-project-memory",0);JSONArray legacy=new JSONArray().put(new JSONObject().put("text","Tony vive en el bosque").put("saved",12)).put(new JSONObject().put("text","Milo es detective").put("saved",13));p.edit().putString("facts",legacy.toString()).commit();String list=ProjectMemory.reply(c,"mis recuerdos");check(list.contains("[1]")&&list.contains("[2]"),"legacy IDs stable");ProjectMemory.reply(c,"corregí el recuerdo 1: Tony vive en la ciudad");JSONArray rows=new JSONArray(p.getString("facts","[]"));check(rows.getJSONObject(0).getLong("saved")==12&&rows.getJSONObject(1).getInt("id")==2&&rows.getJSONObject(1).getString("text").equals("Milo es detective"),"migration preserves provenance and untouched memory");String previous=p.getString("facts","");ProjectMemory.reply(c,"recorda que TONY VIVE EN LA CIUDAD");check(p.getString("facts","").equals(previous),"case-insensitive duplicate does not allocate ID");ProjectMemory.reply(c,"olvida mis recuerdos");ProjectMemory.reply(c,"recorda que el proyecto es de misterio");check(ProjectMemory.reply(c,"mis recuerdos").contains("[3]"),"clear does not reuse deleted IDs");
 p.edit().putString("facts","broken-json").commit();check(ProjectMemory.reply(c,"hola")==null,"corrupt memory does not block ordinary commands");check(ProjectMemory.related(c,"Tony").isEmpty(),"corrupt memory never leaks to generative context");check(ProjectMemory.reply(c,"mis recuerdos").contains("No los modifiqué")&&p.getString("facts","").equals("broken-json"),"corrupt user data is not silently overwritten");
 JSONArray full=new JSONArray();for(int i=1;i<=100;i++)full.put(new JSONObject().put("id",i).put("text","dato numero "+i));p.edit().putString("facts",full.toString()).commit();previous=p.getString("facts","");check(ProjectMemory.reply(c,"recorda que esto no debe borrar recuerdos").contains("100")&&previous.equals(p.getString("facts","")),"capacity never evicts existing facts silently");System.out.println("PASS legacy memory migration, provenance, duplicate handling, stable IDs after clear, corruption isolation and capacity without eviction");}
}
